void W906_CmdServersEnsure()
{
    if (fMain != 0 && fMain->TCPCommandServer == 0 && fMain->TeraTCPResultServer == 0)
        W906_TcpServersCreate(fMain);
}

void W906_CmdServerPumpInit(bool bRealSockets)
{
    W906_CmdServersEnsure();
    if (g_inited || fMain == 0 || fMain->TCPCommandServer == 0 || fMain->TeraTCPResultServer == 0)
        return;
    g_inited = true;
    g_formShown = false;
    g_tickThread = 0;
    g_cmd = fMain->TCPCommandServer;
    g_res = fMain->TeraTCPResultServer;
    TServerSocket* const both[2] = { g_cmd, g_res };
    for (int i = 0; i < 2; ++i)
    {
        both[i]->SetPolled(true);
        if (bRealSockets)
        {
            both[i]->SetExclusiveAddr(true);   // a second listener on 7016 / 7017 fails instead of sharing the port
            both[i]->SetSimMode(false);        // takes effect at the next Open() (golden HanderTcpIp: Close / Open)
        }
    }
    // R2: the framer sits between the socket and the golden body.  The golden dfm binding (OnClientRead =
    //   TCPCommandServerClientRead, forms/fMain.cpp W906_TcpServersCreate) becomes "append here, hand over complete
    //   commands in Pass()"; a disconnect also forgets that connection's half command.
    g_goldenRead = g_cmd->OnClientRead;
    g_goldenDisconnect = g_cmd->OnClientDisconnect;
    g_cmd->OnClientRead = &OnCmdRead;
    const TSocketNotifyEvent golden = g_goldenDisconnect;
    g_cmd->OnClientDisconnect = [golden](TObject* s, TCustomWinSocket* k) {
        g_framer.Drop(k);
        if (golden)
            golden(s, k);
    };
    {
        webbridge::WbGuard g(StatsMu());
        g_stats = W906CmdServerPumpStats();
    }
}

void W906_TcpServersCreate(TfMain* self)
{
    self->TeraTCPResultServer = new TServerSocket(NULL);
    self->TeraTCPResultServer->OnClientConnect    = [self](TObject* s, TCustomWinSocket* k) { self->TeraTCPResultServerClientConnect(s, k); };
    self->TeraTCPResultServer->OnClientDisconnect = [self](TObject* s, TCustomWinSocket* k) { self->TeraTCPResultServerClientDisconnect(s, k); };
    self->TeraTCPResultServer->OnClientError      = [self](TObject* s, TCustomWinSocket* k, TErrorEvent e, int& c) { self->TeraTCPResultServerClientError(s, k, e, c); };
    self->TCPCommandServer = new TServerSocket(NULL);
    self->TCPCommandServer->OnClientConnect    = [self](TObject* s, TCustomWinSocket* k) { self->TCPCommandServerClientConnect(s, k); };
    self->TCPCommandServer->OnClientDisconnect = [self](TObject* s, TCustomWinSocket* k) { self->TCPCommandServerClientDisconnect(s, k); };
    self->TCPCommandServer->OnClientRead       = [self](TObject* s, TCustomWinSocket* k) { self->TCPCommandServerClientRead(s, k); };
}

bool THandlerTesterSide::OffLineGpibWay()
{
    //AI(W906-GB-P2d) 20260926: USER RULINGS 20260926 (github-59 relayed, FROM_STEVEN §1 P2d row):
    //   "on line 時, 各走各的；off line 時, 統一走 gpib 的方式就好", then "流程上就是跑 GPIB 程式在 off line 模式時
    //   會做的事情" and "使用 GPIB 的相關設定".  So while not ON_LINE (the same test as golden's bSimulate,
    //   main.cpp:19083), an RS232 / TTL recipe gets the GPIB engine in simulate -- no Tester / TTL COM port is
    //   opened -- and every packet is filled the GPIB way.  DEVIATION from golden for RS232 / TTL only: golden
    //   runs RS232Standard.exe in its own simulate mode with its COM ports open (Rs232Ui.cpp:2334,
    //   Rs232HandlerMsg.cpp:717-744).  GPIB and TCP/IP recipes already go the GPIB way in golden.
    return LastSet.iTester!=ON_LINE &&
           (TestIF.iTestType==RS232_MODE || TestIF_File.iTestType==TTL_MODE);
}

bool THandlerTesterSide::StartBridgeProgram()
{
    // golden CreateProcess(d:\gpib9045\H9046_32GPIB.exe / d:\RS232Standard\RS232Standard.exe), and
    // TerminateProcess of the old one when TestIF.iTestType changed (WakeupGPIB).  Which engine serves which type
    // is registered by the composition root (P3): GPIB_MODE -> GpibEngine, RS232_MODE and TTL_MODE -> Rs232Engine.
    if (hub == 0)
        return false;
    const int t = EffectiveBridgeTestType();   //AI(W906-GB-P2d) 20260926: the Off-Line rule (see OffLineGpibWay)
    PublishSettings();                          //AI(W906-GB-P6) 20260926: before the engine starts / restarts (its FormShow reads them)
    if (hub->CurrentTestType() != t || !hub->IsUp())
        W906_GpibAuxBeforeBridgeStart(t);       //AI(W906-GB-P6) 20260926: 2A + Q2(a) -- seeds the recipe once, publishes the framing LoadSetupData reads
    if (hub->CurrentTestType() != t)
        return hub->SelectTestType(t);
    if (!hub->IsUp())
        return hub->Restart();   // it closed itself (golden: the exe exited and is launched again)
    return true;
}
